+import AutomationEditor from '@src/views/Automations/editor';
+import React from 'react';
+import {AutomationDetail} from '@tryghost/admin-x-framework/api/automations';
+import {MemoryRouter, Route, Routes} from 'react-router';
+import {beforeEach, describe, expect, it, vi} from 'vitest';
+import {fireEvent, render, screen, waitFor, within} from '@testing-library/react';
+
+const mockUseReadAutomation = vi.fn();
+const mockEditMutation = {mutate: vi.fn(), isLoading: false, variables: undefined as any};
+vi.mock('@tryghost/admin-x-framework/api/automations', async () => {
+    const actual = await vi.importActual<any>('@tryghost/admin-x-framework/api/automations');
+    return {...actual, useReadAutomation: (...a: unknown[]) => mockUseReadAutomation(...a), useEditAutomation: () => mockEditMutation};
+});
+vi.mock('@xyflow/react', async () => {
+    const actual = await vi.importActual<any>('@xyflow/react');
+    return {...actual,
+        ReactFlow: ({nodes, nodeTypes, onPaneClick}: any) => (<div data-testid='react-flow-mock' onClick={onPaneClick}>{nodes.map((n: any)=>{const C=nodeTypes?.[n.type??'default'];return <div key={n.id} data-node-id={n.id}>{C?<C data={n.data??{}} id={n.id} type={n.type}/>:null}</div>;})}</div>),
+        Background: () => null, Handle: () => null, BaseEdge: () => null,
+        EdgeLabelRenderer: ({children}: any) => <>{children}</>, getSmoothStepPath: () => ['M 0 0', 0, 0]};
+});
+const automationDetail: AutomationDetail = {id:'automation-id-1',slug:'member-welcome-email-free',name:'W',status:'active',created_at:'x',updated_at:'x',actions:[{id:'action-wait',type:'wait',data:{wait_hours:24}},{id:'action-email',type:'send_email',data:{email_subject:'S',email_lexical:'{}',email_sender_name:null,email_sender_email:null,email_sender_reply_to:null,email_design_setting_id:'d'}}],edges:[{source_action_id:'action-wait',target_action_id:'action-email'}]};
+const renderEditor = () => render(<MemoryRouter initialEntries={['/automations/automation-id-1']}><Routes><Route element={<AutomationEditor />} path='/automations/:id' /></Routes></MemoryRouter>);
+const stage = async () => { fireEvent.click(screen.getByTestId('add-step-tail-button')); const p = await screen.findByTestId('step-picker'); fireEvent.click(within(p).getByText('Wait')); };
+
+describe('update dialog', () => {
+  beforeEach(() => { mockUseReadAutomation.mockReset(); mockEditMutation.mutate.mockReset(); mockUseReadAutomation.mockReturnValue({data:{automations:[automationDetail]},isLoading:false,isError:false}); });
+
+  it('opens dialog, no direct mutate', async () => {
+    renderEditor(); await stage();
+    fireEvent.click(screen.getByRole('button',{name:'Publish changes'}));
+    expect(mockEditMutation.mutate).not.toHaveBeenCalled();
+    const dlg = screen.getByRole('alertdialog',{name:'Update automation?'});
+    expect(dlg).toBeInTheDocument();
+    expect(within(dlg).getByText(/new runs/i)).toBeInTheDocument();
+    expect(within(dlg).getByText(/in progress/i)).toBeInTheDocument();
+  });
+
+  it('confirm fires mutate with active status', async () => {
+    renderEditor(); await stage();
+    fireEvent.click(screen.getByRole('button',{name:'Publish changes'}));
+    const dlg = screen.getByRole('alertdialog',{name:'Update automation?'});
+    fireEvent.click(within(dlg).getByRole('button',{name:'Publish changes'}));
+    const call = mockEditMutation.mutate.mock.calls.at(-1)![0];
+    expect(call.status).toBe('active'); expect(call.id).toBe('automation-id-1');
+    expect(Array.isArray(call.actions)).toBe(true); expect(Array.isArray(call.edges)).toBe(true);
+  });
+
+  it('in-flight shows Publishing... disabled with spinner', async () => {
+    mockEditMutation.mutate.mockImplementation(() => {});
+    renderEditor(); await stage();
+    fireEvent.click(screen.getByRole('button',{name:'Publish changes'}));
+    const dlg = screen.getByRole('alertdialog',{name:'Update automation?'});
+    fireEvent.click(within(dlg).getByRole('button',{name:'Publish changes'}));
+    const btn = within(screen.getByRole('alertdialog')).getByRole('button',{name:'Publishing...'});
+    expect(btn).toBeDisabled(); expect(btn.querySelector('.animate-spin')).toBeInTheDocument();
+  });
+
+  it('error keeps dialog open and shows Retry', async () => {
+    mockEditMutation.mutate.mockImplementation((_p:any,o:any)=>o.onError());
+    renderEditor(); await stage();
+    fireEvent.click(screen.getByRole('button',{name:'Publish changes'}));
+    fireEvent.click(within(screen.getByRole('alertdialog')).getByRole('button',{name:'Publish changes'}));
+    const retry = await within(screen.getByRole('alertdialog')).findByRole('button',{name:'Retry'});
+    expect(retry).not.toBeDisabled(); expect(retry).toHaveClass('bg-destructive');
+    expect(screen.getByRole('alertdialog',{name:'Update automation?'})).toBeInTheDocument();
+  });
+});
